def bridge(x, mode):
    cols = [np.ones(len(x)), *x.T]
    if mode == 'quadratic':
        cols += [x[:, i] * x[:, j] for i in range(4) for j in range(i, 4)]
    if mode == 'rational':
        cols += [(x[:, i] + sign * x[:, j]) / (1 + 0.25 * (x[:, i] - sign * x[:, j]) ** 2) for i in range(4) for j in range(i + 1, 4) for sign in (-1, 1)]
    return np.column_stack(cols)
